mapper.select:
SELECT B.BOARD_ID, B.TITLE, B.REGISTER, B.REGIST_DT, B.ASK_TYPE, CASE WHEN A.BOARD_ID IS NULL THEN '미답변' ELSE '답변완료' END AS ANSWER_STATUS FROM BOARD B LEFT JOIN QNA_ANSWER A ON B.BOARD_ID = A.BOARD_ID WHERE B.BOARD_TYPE = 'QNA'
AND B.ASK_TYPE = 'PUBLIC'
AND B.ASK_TYPE = #{askType}
AND B.TITLE LIKE '%' || #{searchKeyword} || '%'
ORDER BY B.REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.delete:
DELETE FROM BOARD
WHERE BOARD_ID = #{boardId}
	AND BOARD_TYPE = 'QNA'
